svg.script:
(() => {
  const ns = 'http://www.w3.org/2000/svg';
  const tokens = ['小猫', '坐在', '柔软的', '垫子', '上', '。'];
  const matrix = [
    [.30,.08,.18,.28,.10,.06], [.22,.33,.07,.20,.12,.06],
    [.12,.05,.25,.48,.06,.04], [.35,.08,.24,.20,.08,.05],
    [.12,.16,.05,.42,.20,.05], [.10,.08,.06,.16,.10,.50]
  ];
  const xs = [92,191,290,389,488,587];
  const targetRow = document.getElementById('targetRow');
  const queryRow = document.getElementById('queryRow');
  const flows = document.getElementById('flows');
  const status = document.getElementById('status');

  function el(name, attrs = {}, text = '') {
    const node = document.createElementNS(ns, name);
    Object.entries(attrs).forEach(([k,v]) => node.setAttribute(k,v));
    if (text) node.textContent = text;
    return node;
  }
  function tokenNode(label, x, y, i, interactive) {
    const g = el('g', {class: interactive ? 'token query-token' : 'token target-token', transform:`translate(${x-38} ${y})`});
    if (interactive) Object.entries({role:'button', tabindex:'0', 'aria-label':`选择 ${label} 查看注意力`, 'data-index':i}).forEach(([k,v])=>g.setAttribute(k,v));
    g.append(el('rect',{width:76,height:44,rx:8,fill:'#EEEDFE',stroke:'#534AB7','stroke-width':.5}));
    g.append(el('text',{x:38,y:22,'text-anchor':'middle','dominant-baseline':'central','font-family':'system-ui, -apple-system, sans-serif','font-size':14,'font-weight':500,fill:'#3C3489'},label));
    return g;
  }
  tokens.forEach((token,i) => {
    targetRow.append(tokenNode(token,xs[i],140,i,false));
    queryRow.append(tokenNode(token,xs[i],426,i,true));
  });

  function select(index) {
    flows.replaceChildren();
    document.querySelectorAll('.query-token').forEach((n,i)=>n.classList.toggle('selected',i===index));
    matrix[index].forEach((weight,j) => {
      const startX = xs[index], endX = xs[j];
      const bend = 292 - Math.abs(index-j)*6;
      const path = el('path', {class:'flow', d:`M ${startX} 426 C ${startX} ${bend}, ${endX} ${bend}, ${endX} 184`, fill:'none', stroke:'#534AB7','stroke-linecap':'round','marker-end':'url(#arrow)', style:`--weight:${weight};--strength:${Math.max(.34,weight*1.7)}`});
      const label = el('g',{class:'weight'});
      const lx = endX, ly = 203;
      label.append(el('rect',{x:lx-18,y:ly-9,width:36,height:18,rx:4,fill:'#FFFFFF',stroke:'#AFA9EC','stroke-width':.5}));
      label.append(el('text',{x:lx,y:ly,'text-anchor':'middle','dominant-baseline':'central','font-family':'system-ui, -apple-system, sans-serif','font-size':12,fill:'#3C3489'},Math.round(weight*100)+'%'));
      flows.append(path,label);
      requestAnimationFrame(()=>{path.classList.add('active');label.classList.add('active');});
    });
    status.textContent = `“${tokens[index]}” 的注意力分布`;
  }
  function reset() {
    flows.replaceChildren();
    document.querySelectorAll('.query-token').forEach(n=>n.classList.remove('selected'));
    status.textContent = '尚未选择 token';
  }
  document.querySelectorAll('.query-token').forEach(n => {
    n.addEventListener('click',()=>select(+n.dataset.index));
    n.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(+n.dataset.index);}});
  });
  const resetButton=document.getElementById('reset');
  resetButton.addEventListener('click',reset);
  resetButton.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();reset();}});
})();
